import React, { Suspense } from 'react';
import { Box, CircularProgress, Tab, Tabs, Typography } from '@mui/material';
import { useSearchParams } from 'react-router-dom';
import WorkspacePageHeader from './shared/WorkspacePageHeader';
import GovernmentSchemeBoard from './shared/GovernmentSchemeBoard';
import { lazyWithRetry } from '../utils/lazyWithRetry';
import { useNavVisibility } from '../hooks/useNavVisibility';
import {
  CARBON_SAVINGS_TRADING_SECTIONS,
  carbonSavingsTradingSection,
  type CarbonSavingsTradingSectionId,
} from '../constants/carbonSavingsTrading';

const CarbonSavings = lazyWithRetry(() => import('./CarbonSavings'));
const EmissionsReductionTargets = lazyWithRetry(() => import('./EmissionsReductionTargets'));
const CarbonTrading = lazyWithRetry(() => import('./CarbonTrading'));

const SECTION_COPY: Record<CarbonSavingsTradingSectionId, string> = {
  savings: 'Kilograms already cut between footprint snapshots.',
  cut: 'The reduction target for this year and for a longer period.',
  schemes: 'Official government sites. This workspace does not file applications.',
  trading: 'Offset projects, the credits wallet, prices, and past trades.',
};

const SectionFallback: React.FC = () => (
  <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
    <CircularProgress />
  </Box>
);

const CarbonSavingsAndTrading: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const navVisibility = useNavVisibility();
  const showTrading = navVisibility.loading || navVisibility.hasAssessment;
  const requested = carbonSavingsTradingSection(searchParams.toString());
  const section: CarbonSavingsTradingSectionId = requested === 'trading' && !showTrading
    ? 'savings'
    : requested;
  const sections = CARBON_SAVINGS_TRADING_SECTIONS.filter(
    (item) => item.id !== 'trading' || showTrading
  );

  const openSection = (next: CarbonSavingsTradingSectionId) => {
    const params = new URLSearchParams(searchParams);
    params.set('section', next);
    params.delete('tab');
    setSearchParams(params, { replace: true });
  };

  return (
    <Box>
      <WorkspacePageHeader
        title="Reduce and offset"
        description="See the kilograms already saved, set the target, open government scheme sites, then offset what is still left."
      />
      <Tabs
        value={section}
        onChange={(_event, value: CarbonSavingsTradingSectionId) => openSection(value)}
        variant="scrollable"
        scrollButtons="auto"
        aria-label="Reduce and offset"
        sx={{ borderBottom: 1, borderColor: 'divider', mb: 1 }}
      >
        {sections.map((item) => (
          <Tab key={item.id} value={item.id} label={item.label} />
        ))}
      </Tabs>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 720 }}>
        {SECTION_COPY[section]}
      </Typography>

      <Suspense fallback={<SectionFallback />}>
        {section === 'savings' ? <CarbonSavings embedded /> : null}
        {section === 'cut' ? <EmissionsReductionTargets embedded /> : null}
        {section === 'schemes' ? <GovernmentSchemeBoard /> : null}
        {section === 'trading' ? <CarbonTrading embedded /> : null}
      </Suspense>
    </Box>
  );
};

export default CarbonSavingsAndTrading;
